    },
    {
      "finding_id": "F06",
      "category": "candidate_reuse",
      "row_ids": [
        "REG-A-014",
        "REG-C-014"
      ],
      "note_ids": [
        "NOTE-006",
        "NOTE-007"
      ],
      "expected_outcome": "Flag FLT-100 / FLT-200 for engineering review; common interface alone does not approve gasket or filter substitution.",
      "approval_status": "not_approved"
    },
    {
      "finding_id": "F07",
      "category": "incompatible_near_match",
      "row_ids": [
        "REG-A-027",
        "REG-C-027"
      ],
      "note_ids": [
        "NOTE-009",
        "NOTE-010"
      ],
      "expected_outcome": "Keep CAB-240 and CAB-110 separate despite matching descriptions and dimensions; their input voltages and harnesses differ."
    },
    {
      "finding_id": "F08",
      "category": "conflicting_attribute",
      "row_ids": [
        "REG-A-037",
        "REG-C-037"
      ],
      "note_ids": [
        "NOTE-011"
      ],
      "expected_outcome": "Flag 20 versus 25 mm for the same reference and revision; do not silently overwrite either source value."
    },
